import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int u, v;
        int cap, flow, cost;
        public Edge(int u, int v, int cap, int flow, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static class MCMF {
        int n, m, s, t;
        List<Integer>[] G;
        List<Edge> E;
        int[] p;
        int[] inq;
        int[] d;
        int[] a;

        public MCMF(int n) {
            this.n = n;
            G = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                G[i] = new ArrayList<>();
            }
            E = new ArrayList<>();
            p = new int[n];
            inq = new int[n];
            d = new int[n];
            a = new int[n];
        }

        void addEdge(int u, int v, int cap, int cost) {
            E.add(new Edge(u, v, cap, 0, cost));
            E.add(new Edge(v, u, 0, 0, -cost));
            int m = E.size();
            G[u].add(m - 2);
            G[v].add(m - 1);
        }

        boolean BelmanFord(int[] flowCost) {
            Arrays.fill(d, Integer.MAX_VALUE);
            Arrays.fill(inq, 0);
            d[s] = 0;
            p[s] = -1;
            a[s] = Integer.MAX_VALUE;
            Queue<Integer> Q = new LinkedList<>();
            Q.offer(s);
            inq[s] = 1;

            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = 0;
                for (int i : G[u]) {
                    Edge e = E.get(i);
                    if (e.cap > e.flow && d[e.v] > d[u] + e.cost) {
                        d[e.v] = d[u] + e.cost;
                        p[e.v] = i;
                        a[e.v] = Math.min(a[u], e.cap - e.flow);
                        if (inq[e.v] == 0) {
                            Q.offer(e.v);
                            inq[e.v] = 1;
                        }
                    }
                }
            }
            if (d[t] == Integer.MAX_VALUE) {
                flowCost[0] = 0;
                flowCost[1] = 0;
                return false;
            }
            flowCost[0] = a[t];
            flowCost[1] = d[t];
            int u = t;
            while (u != s) {
                int i = p[u];
                E.get(i).flow += a[t];
                E.get(i ^ 1).flow -= a[t];
                u = E.get(i).u;
            }
            return true;
        }

        int[] Mincost(int s, int t) {
            this.s = s;
            this.t = t;
            int totalFlow = 0;
            int totalCost = 0;
            int[] flowCost = new int[2];
            while (BelmanFord(flowCost)) {
                totalFlow += flowCost[0];
                totalCost += flowCost[0] * flowCost[1];
            }
            return new int[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(br.readLine());

        int size = n * k + 2;
        int source = n * k;
        int sink = n * k + 1;

        MCMF solver = new MCMF(size);

        for (int i = 0; i < k; i++) {
            solver.addEdge(i, sink, k, C * i);
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            int x = Integer.parseInt(st.nextToken()) - 1;
            solver.addEdge(source, x * k, 1, 0);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < k; j++) {
                solver.addEdge(i * k + j - 1, i * k + j, k, 0);
            }
        }

        for (int _ = 0; _ < m; _++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int j = 1, cc = D; j <= k; j++, cc += 2 * D) {
                int a = u * k + j - 1;
                int b = v * k + j;
                int c = v * k + j - 1;
                int d = u * k + j;
                for (int i = 1, cost = D; i <= k; i++, cost += 2 * D) {
                    solver.addEdge(a, b, 1, cost);
                    solver.addEdge(c, d, 1, cost);
                }
            }
        }

        int[] result = solver.Mincost(source, sink);
        System.out.println(result[1]);
    }
}
